#!/usr/bin/env python3
"""
Final solver: balance constraints with diversity targeting.
"""

import json
from collections import defaultdict
from typing import Dict, List, Tuple

def load_data(input_dir):
    shipments = {}
    with open(f"{input_dir}/shipments.jsonl") as f:
        for line in f:
            shipments[int(json.loads(line)['shipment_id'])] = json.loads(line)

    warehouses = {}
    with open(f"{input_dir}/warehouses.jsonl") as f:
        for line in f:
            warehouses[int(json.loads(line)['warehouse_id'])] = json.loads(line)

    destinations = {}
    with open(f"{input_dir}/destinations.jsonl") as f:
        for line in f:
            destinations[int(json.loads(line)['destination_id'])] = json.loads(line)

    routes_by_key = {}
    with open(f"{input_dir}/routes.jsonl") as f:
        for line in f:
            r = json.loads(line)
            routes_by_key[(r['warehouse_id'], r['destination_id'])] = r

    return shipments, warehouses, destinations, routes_by_key

def solve(shipments, warehouses, destinations, routes_by_key):
    """Assign shipments with constraint satisfaction and diversity."""

    # Group shipments by destination
    shipments_by_dest = defaultdict(list)
    for sid, s in shipments.items():
        shipments_by_dest[s['destination_id']].append(sid)

    # Get warehouse info
    wh_caps = {wid: wh['volume_capacity'] for wid, wh in warehouses.items()}
    wh_weights = {wid: wh['weight_capacity'] for wid, wh in warehouses.items()}
    wh_base_cost = {wid: wh['base_handling_cost'] for wid, wh in warehouses.items()}
    wh_is_hub = {wid: wh['is_hub'] for wid, wh in warehouses.items()}
    wh_hazmat = {wid: wh['handles_hazmat'] for wid, wh in warehouses.items()}
    wh_refrig = {wid: wh['handles_refrigerated'] for wid, wh in warehouses.items()}
    wh_oversized = {wid: wh['handles_oversized'] for wid, wh in warehouses.items()}

    # State tracking
    assignment = {}
    wh_volume = defaultdict(int)
    wh_weight = defaultdict(int)
    route_vol = defaultdict(int)
    route_wt = defaultdict(int)
    wh_shipments = defaultdict(list)
    pair_usage = defaultdict(int)  # (wh_id, dest_id) -> count

    # Process each destination
    for dest_id in sorted(shipments_by_dest.keys()):
        dest = destinations[dest_id]
        dest_shipments = shipments_by_dest[dest_id]

        # Sort shipments by deadline (tightest first)
        dest_shipments.sort(key=lambda sid: shipments[sid]['deadline_hours'])

        # Get all warehouses that can serve this destination
        valid_wh_for_dest = []
        for wh_id in warehouses:
            route_key = (wh_id, dest_id)
            if route_key not in routes_by_key:
                continue
            route = routes_by_key[route_key]

            # Check basic feasibility
            if not (warehouses[wh_id]['availability_start'] < warehouses[wh_id]['availability_end']):
                continue
            if not (dest['delivery_window_end'] >= warehouses[wh_id]['availability_start']):
                continue
            arrival = warehouses[wh_id]['availability_start'] + route['transit_time_hours']
            if not (dest['delivery_window_start'] <= arrival <= dest['delivery_window_end']):
                continue

            valid_wh_for_dest.append((wh_id, route))

        for sid in dest_shipments:
            s = shipments[sid]
            vol = s['volume']
            wt = s['weight']
            req_hazmat = s['requires_hazmat']
            req_refrig = s['requires_refrigerated']
            req_oversized = s['requires_oversized']

            # Find valid candidates respecting requirements
            candidates = []
            for wh_id, route in valid_wh_for_dest:
                # Route capability checks
                if req_hazmat and not route['allows_hazmat']:
                    continue
                if req_refrig and not route['allows_refrigerated']:
                    continue
                if req_oversized and not route['allows_oversized']:
                    continue

                # Warehouse capability checks
                if req_hazmat and not wh_hazmat[wh_id]:
                    continue
                if req_refrig and not wh_refrig[wh_id]:
                    continue
                if req_oversized and not wh_oversized[wh_id]:
                    continue

                # Deadline check
                arrival = warehouses[wh_id]['availability_start'] + route['transit_time_hours']
                if arrival > s['deadline_hours']:
                    continue

                # Capacity checks
                if wh_volume[wh_id] + vol > wh_caps[wh_id]:
                    continue
                if wh_weight[wh_id] + wt > wh_weights[wh_id]:
                    continue

                # Route capacity checks
                if route_vol[(wh_id, dest_id)] + vol > route['capacity_volume']:
                    continue
                if route_wt[(wh_id, dest_id)] + wt > route['capacity_weight']:
                    continue

                # Constraint 13: no hazmat + refrigerated mix
                wh_list = wh_shipments[wh_id]
                has_hazmat = any(shipments[wsid]['requires_hazmat'] for wsid in wh_list)
                has_refrig = any(shipments[wsid]['requires_refrigerated'] for wsid in wh_list)
                if has_hazmat and has_refrig:
                    continue

                candidates.append((wh_id, route))

            if not candidates:
                print(f"ERROR: No valid warehouse for shipment {sid}")
                return None

            # Sort by: pair usage (for diversity), then cost (for optimization)
            def score_key(wh_id, route):
                pair_key = (wh_id, dest_id)
                usage = pair_usage[pair_key]
                cost = (wh_base_cost[wh_id] * (vol/100) + route['base_cost_per_km']*route['distance_km']*(wt/1000)) * s['priority_multiplier']
                return (usage, cost)

            candidates.sort(key=lambda x: score_key(x[0], x[1]))

            wh_id, route = candidates[0]
            assignment[sid] = (wh_id, route)
            wh_volume[wh_id] += vol
            wh_weight[wh_id] += wt
            route_vol[(wh_id, dest_id)] += vol
            route_wt[(wh_id, dest_id)] += wt
            wh_shipments[wh_id].append(sid)
            pair_usage[(wh_id, dest_id)] += 1

    return assignment

def main():
    input_dir = "/app/task_file/input_data"
    output_file = "/app/task_file/output_data/assignments.jsonl"

    import os
    os.makedirs(os.path.dirname(output_file), exist_ok=True)

    shipments, warehouses, destinations, routes_by_key = load_data(input_dir)
    print(f"Loaded {len(shipments)} shipments, {len(warehouses)} warehouses")

    assignment = solve(shipments, warehouses, destinations, routes_by_key)

    if assignment is None:
        print("Failed to find valid assignment!")
        return

    with open(output_file, 'w') as f:
        for sid in sorted(assignment.keys()):
            wh_id, route = assignment[sid]
            f.write(json.dumps({"shipment_id": sid, "warehouse_id": wh_id, "destination_id": route['destination_id']}) + '\n')

    print(f"Generated {len(assignment)} assignments")

    # Check pair count
    pairs = set((a[0], a[1]['destination_id']) for a in assignment.values())
    print(f"Unique (warehouse, destination) pairs: {len(pairs)}")
    print(f"Target for optimal fragmentation: 300-600 pairs")

if __name__ == "__main__":
    main()
